"""cli: Typer entry point for audio-transcribe-cli (atcli).

Commands:
  transcribe  Transcribe an audio/video file to SRT using Soniox API.
  view        Open an existing SRT file in the HTML viewer.
"""
from __future__ import annotations

import json
import os
import tempfile
import webbrowser
from datetime import datetime
from pathlib import Path
from typing import Annotated, Optional

import typer
from dotenv import load_dotenv
from rich.console import Console
from rich.progress import Progress, SpinnerColumn, TextColumn, BarColumn, TaskProgressColumn

from atcli.core.audio_segmenter import extract_audio_if_video
from atcli.core.context_extractor import build_soniox_context
from atcli.core.html_viewer import generate_viewer
from atcli.core.soniox_client import SonioxClient, fetch_demo_api_key
from atcli.core.srt_reviser import revise_srt
from atcli.core.subtitle_generator import generate_srt, split_blocks_on_tags
from atcli.core.token_assembler import render_tokens_to_blocks
from atcli.utils.logger import get_logger

load_dotenv()

app = typer.Typer(
    name="atcli",
    help="Local CLI for audio/video transcription using Soniox API.",
    add_completion=False,
)
console = Console()
logger = get_logger(__name__)


def _resolve_api_key(provided: str | None) -> tuple[str, datetime | None]:
    """Return (api_key, expires_at).

    Resolution order:
    1. --api-key flag / SONIOX_API_KEY env var
    2. Demo temp key from soniox.com (with expiry timestamp for rotation)
    """
    key = provided or os.getenv("SONIOX_API_KEY", "")
    if key:
        return key, None  # permanent key — no expiry tracking needed

    console.print(
        "[yellow]No SONIOX_API_KEY found — fetching a free demo key from soniox.com...[/yellow]"
    )
    console.print(
        "[dim]For long files or repeated use, set SONIOX_API_KEY in .env or via --api-key.[/dim]"
    )
    try:
        demo_key, expires_at = fetch_demo_api_key()
        console.print(
            f"[green]Demo key acquired[/green] (expires {expires_at.strftime('%H:%M:%S')} UTC)"
        )
        return demo_key, expires_at
    except Exception as exc:
        console.print(f"[red]Failed to get demo key:[/red] {exc}")
        console.print("Please set SONIOX_API_KEY: https://console.soniox.com")
        raise typer.Exit(1)


# ── transcribe ────────────────────────────────────────────────────────────────

@app.command()
def transcribe(
    input_file: Annotated[Path, typer.Argument(help="Audio or video file to transcribe.")],
    context: Annotated[
        Optional[list[Path]],
        typer.Option("--context", "-c", help="PDF reference document(s) for Soniox context.", exists=True),
    ] = None,
    context_json: Annotated[
        Optional[Path],
        typer.Option("--context-json", help="Pre-built Soniox context JSON file (e.g. from tkm:audio-transcribe skill). Overrides --context.", exists=True),
    ] = None,
    hints: Annotated[str, typer.Option(help="Free-text hints added to Soniox context.")] = "",
    language: Annotated[
        Optional[str],
        typer.Option(help="Comma-separated language hints, e.g. 'en,ja'. Default: auto-detect."),
    ] = None,
    output: Annotated[
        Optional[Path],
        typer.Option("--output", "-o", help="Output SRT path. Default: <input>.srt next to input file."),
    ] = None,
    view: Annotated[bool, typer.Option("--view/--no-view", help="Open HTML viewer after transcription.")] = True,
    api_key: Annotated[
        Optional[str],
        typer.Option("--api-key", envvar="SONIOX_API_KEY", help="Soniox API key."),
    ] = None,
    llm_api_key: Annotated[
        Optional[str],
        typer.Option(envvar="OPENAI_API_KEY", help="OpenAI-compatible API key for keyword extraction."),
    ] = None,
    llm_endpoint: Annotated[
        Optional[str],
        typer.Option(envvar="OPENAI_ENDPOINT", help="OpenAI-compatible endpoint URL."),
    ] = None,
) -> None:
    """Transcribe an audio/video file to SRT using the Soniox API."""

    if not input_file.exists():
        console.print(f"[red]Error:[/red] File not found: {input_file}")
        raise typer.Exit(1)

    resolved_key, key_expires_at = _resolve_api_key(api_key)
    srt_output = output or input_file.with_suffix(".srt")
    lang_hints = [l.strip() for l in language.split(",")] if language else None
    doc_paths = [str(p) for p in (context or [])]
    use_context_json = context_json is not None

    with tempfile.TemporaryDirectory(prefix="atcli_") as tmp_dir:
        console.rule("[bold]audio-transcribe-cli[/bold]")
        console.print(f"Input : [cyan]{input_file}[/cyan]")
        console.print(f"Output: [cyan]{srt_output}[/cyan]")

        # Step 1: Extract audio from video if needed
        with Progress(SpinnerColumn(), TextColumn("{task.description}"), console=console, transient=True) as p:
            p.add_task("Extracting audio...", total=None)
            audio_path = extract_audio_if_video(str(input_file), tmp_dir)

        # Step 2: Build Soniox context
        soniox_context: dict = {}
        if use_context_json:
            # Load pre-built context JSON (e.g. from tkm:audio-transcribe skill)
            raw = json.loads(context_json.read_text(encoding="utf-8"))  # type: ignore[union-attr]
            # JSON may be wrapped: {"context": {...}} or bare: {"terms": [...], "text": "..."}
            soniox_context = raw.get("context", raw)
            console.print(f"Context: [cyan]{context_json.name}[/cyan] ({len(soniox_context.get('terms', []))} terms)")
        elif doc_paths or hints:
            with Progress(SpinnerColumn(), TextColumn("{task.description}"), console=console, transient=True) as p:
                p.add_task(f"Building context from {len(doc_paths)} doc(s)...", total=None)
                soniox_context = build_soniox_context(
                    doc_paths, hints=hints, llm_api_key=llm_api_key, llm_endpoint=llm_endpoint
                )
            console.print(f"Context: {len(soniox_context.get('terms', []))} keywords extracted.")

        # Step 3 + 4: Transcribe
        # Demo keys use WebSocket micro-chunking internally — no need to pre-segment.
        # Paid keys use the async HTTP API which has file size limits, so we segment first.
        all_blocks: list[dict] = []
        is_demo_key = resolved_key.startswith("temp:")

        with SonioxClient(resolved_key, key_expires_at=key_expires_at) as client:
            if is_demo_key:
                # Fast path: stream entire file as parallel 4s micro-chunks
                with Progress(SpinnerColumn(), TextColumn("{task.description}"), console=console, transient=True) as p:
                    p.add_task("Transcribing (parallel WebSocket)...", total=None)
                    tokens = client.transcribe_file(audio_path, context=soniox_context, language_hints=lang_hints)
                blocks = render_tokens_to_blocks(tokens, segment_offset_ms=0)
                all_blocks.extend(blocks)
            else:
                # Paid key: send full audio file in one shot for full-context async transcription.
                # The async API processes the entire file as a unit — no boundary artifacts.
                with Progress(SpinnerColumn(), TextColumn("{task.description}"), console=console, transient=True) as p:
                    p.add_task("Transcribing (async full-file)...", total=None)
                    tokens = client.transcribe_file(audio_path, context=soniox_context, language_hints=lang_hints)
                blocks = render_tokens_to_blocks(tokens, segment_offset_ms=0)
                all_blocks.extend(blocks)

        # Step 5: Resolve split tags → final subtitle blocks
        raw_blocks = split_blocks_on_tags(all_blocks)

        # Drop sub-word boundary artifacts: very short cues with no sentence punctuation.
        # These arise from micro-segment boundaries where a word straddles a 4s cut.
        def _is_fragment(block: dict) -> bool:
            text = block.get("text", "").strip()
            duration = (block.get("end_ms") or 0) - (block.get("start_ms") or 0)
            has_punctuation = any(c in text for c in ".!?,。！？，、")
            return len(text) <= 5 and duration < 400 and not has_punctuation

        final_blocks = [b for b in raw_blocks if not _is_fragment(b)]
        console.print(f"Subtitles: [bold]{len(final_blocks)}[/bold] cue(s) generated.")

        # Step 6: Write SRT
        srt_text = generate_srt(final_blocks)
        srt_output.write_text(srt_text, encoding="utf-8")
        console.print(f"[green]SRT written:[/green] {srt_output}")

        # Step 7: Generate and open HTML viewer
        if view:
            viewer_path = generate_viewer(str(srt_output))
            console.print(f"[green]Viewer:[/green] {viewer_path}")
            webbrowser.open(f"file://{viewer_path}")


# ── view ──────────────────────────────────────────────────────────────────────

@app.command()
def view(
    srt_file: Annotated[Path, typer.Argument(help="SRT file to open in the viewer.")],
    media: Annotated[
        Optional[Path],
        typer.Option(help="Media file path (informational; viewer uses file picker for browser compatibility)."),
    ] = None,
) -> None:
    """Open an existing SRT file in the self-contained HTML viewer."""
    if not srt_file.exists():
        console.print(f"[red]Error:[/red] SRT file not found: {srt_file}")
        raise typer.Exit(1)

    viewer_path = generate_viewer(str(srt_file), media_path=str(media) if media else None)
    console.print(f"[green]Viewer generated:[/green] {viewer_path}")
    webbrowser.open(f"file://{viewer_path}")


# ── revise ───────────────────────────────────────────────────────────────────

@app.command()
def revise(
    srt_file: Annotated[Path, typer.Argument(help="SRT file to revise.")],
    context: Annotated[
        Optional[list[Path]],
        typer.Option("--context", "-c", help="Reference document(s) (PDF/text) for correction context.", exists=True),
    ] = None,
    hints: Annotated[str, typer.Option(help="Free-text hints: topic, speaker names, domain terms.")] = "",
    output: Annotated[
        Optional[Path],
        typer.Option("--output", "-o", help="Output path. Default: <input>_revised.srt next to input."),
    ] = None,
    model: Annotated[str, typer.Option(help="LLM model for revision.")] = "gpt-4o-mini",
    view: Annotated[bool, typer.Option("--view/--no-view", help="Open HTML viewer after revision.")] = True,
    llm_api_key: Annotated[
        Optional[str],
        typer.Option(envvar="OPENAI_API_KEY", help="OpenAI-compatible API key."),
    ] = None,
    llm_endpoint: Annotated[
        Optional[str],
        typer.Option(envvar="OPENAI_ENDPOINT", help="API base URL (default: OpenAI)."),
    ] = None,
) -> None:
    """Revise an SRT transcription using LLM and optional reference documents.

    Corrects proper nouns, technical terms, and mis-transcriptions while
    preserving all timestamps exactly. Safe to re-run on the same file.
    """
    if not srt_file.exists():
        console.print(f"[red]Error:[/red] SRT not found: {srt_file}")
        raise typer.Exit(1)

    if not llm_api_key:
        console.print("[red]Error:[/red] LLM API key required (--llm-api-key or OPENAI_API_KEY env var).")
        raise typer.Exit(1)

    srt_output = output or srt_file.with_stem(srt_file.stem + "_revised")
    doc_paths = [str(p) for p in (context or [])]

    console.rule("[bold]SRT Revision[/bold]")
    console.print(f"Input : [cyan]{srt_file}[/cyan]")
    console.print(f"Output: [cyan]{srt_output}[/cyan]")
    if doc_paths:
        console.print(f"Context: {len(doc_paths)} document(s)")

    srt_text = srt_file.read_text(encoding="utf-8")

    with Progress(SpinnerColumn(), TextColumn("{task.description}"), console=console, transient=True) as p:
        p.add_task(f"Revising with {model}...", total=None)
        revised_text = revise_srt(
            srt_text=srt_text,
            context_docs=doc_paths,
            hints=hints,
            api_key=llm_api_key,
            endpoint=llm_endpoint or "",
            model=model,
        )

    srt_output.write_text(revised_text, encoding="utf-8")
    console.print(f"[green]Revised SRT written:[/green] {srt_output}")

    if view:
        viewer_path = generate_viewer(str(srt_output))
        console.print(f"[green]Viewer:[/green] {viewer_path}")
        webbrowser.open(f"file://{viewer_path}")


# ── entry ─────────────────────────────────────────────────────────────────────

if __name__ == "__main__":
    app()
